"""soil(polygon) -> dict with the polygon mean of SoilGrids (data/raw/soilgrids_pr/, generated by ingest/soil_pam_oeste_pr.py).

PHYSICAL UNITS (already converted at ingestion; SoilGrids 2.0 stores scaled integers):
  clay, sand, silt: % (g/100 g)   [SoilGrids: g/kg  -> /10]
  soc: g/kg of organic C          [SoilGrids: dg/kg -> /10]
  phh2o: pH in water              [SoilGrids: pH×10 -> /10]
  bdod: g/cm³                     [SoilGrids: cg/cm³ -> /100]
Depths: 0-5, 5-15, 15-30, 30-60 cm. 0-30 and 0-60 means weighted by thickness (5, 10, 15, 30 cm).

AWC (available water capacity, mm of water per cm of soil) = (θ33 kPa − θ1500 kPa) × 10.
SoilGrids does NOT publish wv0033/wv1500 on the server (latest/data), so we use the Saxton & Rawls (2006)
pedotransfer function with sand, clay and organic matter (OM = 1.724 × organic C).
WARNING: Saxton & Rawls was calibrated on temperate soils (USDA base); on very clayey, micro-aggregated tropical
oxisols (Oeste do PR) it tends to BE WRONG, usually underestimating θ33 and the AWC
(oxidic clay holds less water at 1500 kPa than the clay content predicts). Treat the AWC as an estimate to validate
(e.g. with a soil analysis / Embrapa).

Input: shapely Polygon/MultiPolygon in EPSG:4326 (or a buffered point). Outside the raster coverage -> SoilGrids API fallback.
"""
from __future__ import annotations

import json
import urllib.request
from functools import lru_cache
from pathlib import Path
from urllib.error import HTTPError, URLError

import numpy as np
import rasterio
from rasterio.features import geometry_mask
from rasterio.windows import Window, from_bounds

ROOT = Path(__file__).resolve().parents[3]
SG = ROOT / "data/raw/soilgrids_pr"
PROPS = ["clay", "sand", "silt", "soc", "phh2o", "bdod"]
PROFS = ["0-5cm", "5-15cm", "15-30cm", "30-60cm"]
THICKNESS = np.array([5.0, 10.0, 15.0, 30.0])  # cm
SCALES = {
    "clay": 10.0,
    "sand": 10.0,
    "silt": 10.0,
    "soc": 10.0,
    "phh2o": 10.0,
    "bdod": 100.0,
}


def cad_mm_cm(sand_pct, clay_pct, soc_g_kg):
    """AWC (mm/cm) by Saxton & Rawls (2006), vectorized. Sand/clay in %, organic C in g/kg."""
    s, c = np.asarray(sand_pct) / 100.0, np.asarray(clay_pct) / 100.0
    om = 1.724 * np.asarray(soc_g_kg) / 10.0  # organic matter %
    t1500 = (-0.024 * s + 0.487 * c + 0.006 * om + 0.005 * s * om - 0.013 * c * om + 0.068 * s * c + 0.031)
    t1500 = t1500 + (0.14 * t1500 - 0.02)
    t33 = (-0.251 * s + 0.195 * c + 0.011 * om + 0.006 * s * om - 0.027 * c * om + 0.452 * s * c + 0.299)
    t33 = t33 + (1.283 * t33 ** 2 - 0.374 * t33 - 0.015)
    return np.maximum(t33 - t1500, 0.0) * 10.0  # cm³/cm³ × 10 = mm/cm


@lru_cache(maxsize=None)
def _src_path(prop: str) -> Path:
    return SG / f"{prop}.tif"


def _polygon_mean(prop: str, g) -> np.ndarray | None:
    """Per-band mean (4 depths) of the pixels whose center falls in the polygon (fallback: touched pixels)."""
    path = _src_path(prop)
    if not path.exists():
        return None
    with rasterio.open(path) as src:
        win = from_bounds(*g.bounds, transform=src.transform).round_offsets().round_lengths()
        win = win.intersection(Window(0, 0, src.width, src.height))
        if win.width <= 0 or win.height <= 0:
            return None
        dados = src.read(window=win)
        tr = src.window_transform(win)
    m = ~geometry_mask([g], out_shape=dados.shape[1:], transform=tr)
    if not m.any():
        m = ~geometry_mask([g], out_shape=dados.shape[1:], transform=tr, all_touched=True)
    v = dados[:, m]
    if v.size == 0 or np.isnan(v).all():
        return None
    return np.nanmean(v, axis=1)


def _pond(v: np.ndarray, n: int) -> float:
    return float(np.sum(v[:n] * THICKNESS[:n]) / THICKNESS[:n].sum())


def _fallback_soilgrids(polygon) -> dict[str, np.ndarray] | None:
    """Query the SoilGrids 2.0 REST API at the representative point inside the polygon."""
    pt = polygon.representative_point()
    props_q = "&".join(f"property={p}" for p in PROPS)
    profs_q = "&".join(f"depth={d}" for d in PROFS)
    url = (
        f"https://rest.isric.org/soilgrids/v2.0/properties/query"
        f"?lon={pt.x:.6f}&lat={pt.y:.6f}&{props_q}&{profs_q}&value=mean"
    )
    req = urllib.request.Request(url, headers={"Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            payload = json.loads(resp.read().decode("utf-8"))
    except (HTTPError, URLError, TimeoutError, ValueError):
        return None

    layers = payload.get("properties", {}).get("layers", [])
    med: dict[str, np.ndarray] = {}
    for layer in layers:
        nome = layer.get("name")
        if nome not in PROPS:
            continue
        by_depth = {}
        for d in layer.get("depths", []):
            label = d.get("label")
            val = d.get("values", {}).get("mean")
            if label in PROFS and val is not None:
                by_depth[label] = float(val) / SCALES[nome]
        if len(by_depth) != len(PROFS):
            return None
        med[nome] = np.array([by_depth[d] for d in PROFS], dtype=float)

    if any(p not in med for p in PROPS):
        return None
    return med


def _build(med: dict[str, np.ndarray], source: str = "raster") -> dict:
    """Build the standardized soil dict from {prop: array(4 depths)}."""
    prof = {p: dict(zip(PROFS, map(float, v))) for p, v in med.items()}
    p30 = {p: _pond(v, 3) for p, v in med.items()}
    p60 = {p: _pond(v, 4) for p, v in med.items()}
    cad_l = cad_mm_cm(med["sand"], med["clay"], med["soc"])  # per layer
    cad = {d: float(c) for d, c in zip(PROFS, cad_l)}
    cad["0-30"], cad["0-60"] = _pond(cad_l, 3), _pond(cad_l, 4)
    clay = p30["clay"]
    class_ = "muito argiloso" if clay >= 60 else "argiloso" if clay >= 35 else "médio" if clay >= 15 else "arenoso"
    return dict(
        prof=prof,
        p30=p30,
        p60=p60,
        cad_mm_cm=cad,
        cad_mm_0_30=cad["0-30"] * 30,
        cad_mm_0_60=cad["0-60"] * 60,
        cad_metodo="Saxton & Rawls (2006) com areia, argila e MO (SoilGrids); wv0033/wv1500 indisponíveis",
        classe_textura=class_,
        fonte=source,
    )


def soil(polygon) -> dict | None:
    """Mean properties in the polygon per depth and weighted over 0-30 and 0-60 cm, plus the AWC.

    Returns a dict:
      prof: {prop: {'0-5cm': x, ...}}, p30: {prop: 0-30 mean}, p60: {prop: 0-60 mean},
      cad_mm_cm: {'0-5cm':.., ..., '0-30': .., '0-60': ..},
      cad_mm_0_30, cad_mm_0_60 (total mm), cad_metodo, classe_textura, fonte.
    None if outside the raster and the SoilGrids fallback also fails."""
    med = {}
    for p in PROPS:
        r = _polygon_mean(p, polygon)
        if r is None:
            med = None
            break
        med[p] = r

    if med is not None:
        return _build(med, source="raster")

    med_fb = _fallback_soilgrids(polygon)
    if med_fb is None:
        return None
    return _build(med_fb, source="soilgrids_api")


ANALYSIS_SOURCE = "análise de solo do produtor"
DEFAULT_OM_PCT = 2.0  # OM assumed only if the analysis brings no OM/organic C, no AWC is given and there is no SoilGrids (estimate)


def soil_from_analysis(a: dict, soc_fallback_g_kg: float | None = None) -> dict:
    """Build the `solo` block (same format as `soil()`) from the farmer's analysis, already validated by the service.

    `a`: argila_pct, areia_pct (both or neither), soc_g_kg (organic C, g/kg; optional), ph, cad_mm_cm, profundidade_cm.
    AWC: a given `cad_mm_cm` is used directly; otherwise Saxton & Rawls with sand, clay and OM (if the analysis brought no OM, uses the
    SoilGrids one passed in `soc_fallback_g_kg`, or 2% OM). The sample (default 0–20 cm) is taken as representative of all
    layers (0–60 cm). Returns a dict with the extra key `avisos` (list) and `fonte`."""
    warnings = []
    clay, sand, soc = a.get("argila_pct"), a.get("areia_pct"), a.get("soc_g_kg")
    if a.get("cad_mm_cm") is not None:
        cad_v, method = float(a["cad_mm_cm"]), "CAD informada pelo produtor (mm/cm)"
    else:
        if soc is None:
            if soc_fallback_g_kg is not None:
                soc = float(soc_fallback_g_kg)
                warnings.append("A análise não traz matéria orgânica: usado o C orgânico do SoilGrids na CAD (Saxton & Rawls).")
            else:
                soc = DEFAULT_OM_PCT / 1.724 * 10.0
                warnings.append(f"A análise não traz matéria orgânica: assumido {DEFAULT_OM_PCT:g}% de MO na CAD (Saxton & Rawls).")
        cad_v = float(cad_mm_cm(sand, clay, soc))
        method = "Saxton & Rawls (2006) com areia, argila e MO da análise do produtor"
    cad = {d: cad_v for d in PROFS}
    cad["0-30"] = cad["0-60"] = cad_v
    silt = None if clay is None else 100.0 - clay - sand
    props = dict(clay=clay, sand=sand, silt=silt, soc=soc if a.get("soc_g_kg") is not None else None,
                 phh2o=a.get("ph"), bdod=None)
    prof = {k: {d: v for d in PROFS} for k, v in props.items()}
    class_ = None if clay is None else ("muito argiloso" if clay >= 60 else "argiloso" if clay >= 35
                                          else "médio" if clay >= 15 else "arenoso")
    return dict(prof=prof, p30=dict(props), p60=dict(props), cad_mm_cm=cad, cad_mm_0_30=cad_v * 30, cad_mm_0_60=cad_v * 60,
                cad_metodo=method, classe_textura=class_, fonte=ANALYSIS_SOURCE, amostra_profundidade_cm=a.get("profundidade_cm", 20.0),
                avisos=warnings)


def text(s: dict) -> str:
    p = s["p30"]
    if s.get("fonte") == ANALYSIS_SOURCE:
        parts = [f"{n} {p[k]:.{d}f}{u}" for n, k, d, u in (("argila", "clay", 0, "%"), ("areia", "sand", 0, "%"),
                                                            ("C orgânico", "soc", 1, " g/kg"), ("pH", "phh2o", 1, ""))
                  if p.get(k) is not None]
        return (f"Análise do produtor ({s['amostra_profundidade_cm']:g} cm, extrapolada ao perfil): " + ", ".join(parts)
                + (", " if parts else "") + f"CAD {s['cad_mm_cm']['0-30']:.2f} mm/cm ({s['cad_mm_0_60']:.0f} mm em 60 cm).")
    return (f"Argila {p['clay']:.0f}%, areia {p['sand']:.0f}%, C orgânico {p['soc']:.1f} g/kg, pH {p['phh2o']:.1f} (0–30 cm); "
            f"CAD {s['cad_mm_cm']['0-30']:.2f} mm/cm ({s['cad_mm_0_60']:.0f} mm em 60 cm).")